import {
  Chart,
  LineElement,
  PointElement,
  RadarController,
  RadialLinearScale,
  Tooltip,
  Filler,
  type ChartData,
} from 'chart.js';

import { currentTheme } from 'lib/device';

Chart.register(RadarController, RadialLinearScale, PointElement, LineElement, Tooltip, Filler);

export function initModule(data: { radar: ChartData<'radar', number, 'Performance'> }) {
  const canvas = document.querySelector('.puzzle-dashboard__radar') as HTMLCanvasElement;
  const d = data.radar;

  if (!d?.datasets.length || !canvas) return;

  d.datasets[0] = {
    ...d.datasets[0],
    backgroundColor: 'rgb(189 130 35 / 0.2)',
    borderColor: 'rgb(189 130 35 / 1)',
    pointBackgroundColor: 'rgb(189 130 35 / 1)',
  };
  const fontColor = currentTheme() === 'dark' ? '#bababa' : '#4d4d4d';
  const lineColor = 'rgb(127 127 127 / 0.3)';

  new Chart(canvas, {
    type: 'radar',
    data: d,
    options: {
      aspectRatio: 2,
      scales: {
        r: {
          beginAtZero: false,
          suggestedMin: Math.min(d.datasets[0].data) - 100,
          ticks: {
            color: fontColor,
            showLabelBackdrop: false, // hide square behind text
            format: {
              useGrouping: false,
            },
          },
          pointLabels: {
            color: fontColor,
            font: {
              size: window.innerWidth < 500 ? 11 : 16,
            },
          },
          grid: {
            color: lineColor,
          },
          angleLines: {
            color: lineColor,
          },
        },
      },
    },
  });
}
